(function execute(inputs, outputs) {
  var HOSTS = {
    api: "https://api.mailgun.net",
    storage_us_east4: "https://storage-us-east4.api.mailgun.net",
    storage_us_west1: "https://storage-us-west1.api.mailgun.net",
    storage_europe_west1: "https://storage-europe-west1.api.mailgun.net"
  };
  outputs.base_url = "";
  outputs.error = "";
  var host = String(inputs.host_1 || "");
  var path = String(inputs.path_1 || "");
  if (!Object.prototype.hasOwnProperty.call(HOSTS, host)) {
    outputs.error = "invalid host";
    return;
  }
  if (!/^\/(v1|v3)\//.test(path) || path.indexOf("..") !== -1 || /[\r\n]/.test(path) || /:\/\//.test(path) || path.indexOf("//") !== -1) {
    outputs.error = "invalid path";
    return;
  }
  outputs.base_url = HOSTS[host];
})(inputs, outputs);

